import datetime

def next_run(expression: str, after: datetime.datetime) -> datetime.datetime | None:
    MONTH_MAP = {
        'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
        'JUL': 7, 'AUG': 8, 'SEP': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12
    }
    WEEKDAY_MAP = {
        'SUN': 0, 'MON': 1, 'TUE': 2, 'WED': 3, 'THU': 4, 'FRI': 5, 'SAT': 6
    }

    def parse_field(field_str, min_val, max_val, name_map=None):
        allowed = set()
        parts = field_str.split(',')
        for part in parts:
            if not part:
                raise ValueError("Empty item")

            def to_val(v):
                if name_map and v.upper() in name_map:
                    return name_map[v.upper()]
                if v.isdigit():
                    return int(v)
                raise ValueError("Invalid value")

            if part == '*':
                for i in range(min_val, max_val + 1):
                    allowed.add(i)
            elif part.startswith('*/'):
                step_str = part[2:]
                if not step_str.isdigit():
                    raise ValueError("Invalid step")
                step = int(step_str)
                if step <= 0:
                    raise ValueError("Step must be positive")
                for i in range(min_val, max_val + 1, step):
                    allowed.add(i)
            elif '/' in part:
                range_part, step_str = part.split('/')
                if not step_str.isdigit():
                    raise ValueError("Invalid step")
                step = int(step_str)
                if step <= 0:
                    raise ValueError("Step must be positive")
                if '-' in range_part:
                    start_str, end_str = range_part.split('-')
                    start, end = to_val(start_str), to_val(end_str)
                    if start > end or start < min_val or end > max_val:
                        raise ValueError("Invalid range")
                    for i in range(start, end + 1, step):
                        allowed.add(i)
                else:
                    raise ValueError("Range required before /")
            elif '-' in part:
                start_str, end_str = part.split('-')
                start, end = to_val(start_str), to_val(end_str)
                if start > end or start < min_val or end > max_val:
                    raise ValueError("Invalid range")
                for i in range(start, end + 1):
                    allowed.add(i)
            else:
                val = to_val(part)
                if val < min_val or val > max_val:
                    raise ValueError("Value out of range")
                allowed.add(val)
        return allowed

    fields = expression.split()
    if len(fields) != 5:
        raise ValueError("Must have 5 fields")

    min_set = parse_field(fields[0], 0, 59)
    hour_set = parse_field(fields[1], 0, 23)
    dom_field = fields[2]
    dom_set = parse_field(dom_field, 1, 31)
    month_set = parse_field(fields[3], 1, 12, MONTH_MAP)
    dow_field = fields[4]
    # Normalize DOW 0-7 to 0-6 (7 becomes 0)
    dow_set_raw = parse_field(dow_field, 0, 7, WEEKDAY_MAP)
    dow_set = {d % 7 for d in dow_set_raw}

    def get_days_in_month(y, m):
        if m in {1, 3, 5, 7, 8, 10, 12}: return 31
        if m in {4, 6, 9, 11}: return 30
        if m == 2:
            return 29 if (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0) else 28
        return 0

    dom_specified = (dom_field != '*')
    dow_specified = (dow_field != '*')

    for y in range(after.year, after.year + 11):
        start_m = after.month if y == after.year else 1
        for m in range(start_m, 13):
            if m not in month_set:
                continue

            days_in_m = get_days_in_month(y, m)
            for d in range(1, days_in_m + 1):
                if y == after.year and m == after.month and d < after.day:
                    continue

                dt_temp = datetime.datetime(y, m, d)
                # Python: Mon=0...Sun=6; Cron: Sun=0...Sat=6
                dow_cron = (dt_temp.weekday() + 1) % 7

                if not dom_specified and not dow_specified:
                    match = True
                elif not dom_specified:
                    match = (dow_cron in dow_set)
                elif not dow_specified:
                    match = (d in dom_set)
                else:
                    match = (d in dom_set or dow_cron in dow_set)

                if not match:
                    continue

                start_h = after.hour if (y == after.year and m == after.month and d == after.day) else 0
                for h in range(start_h, 24):
                    if h not in hour_set:
                        continue

                    start_min = after.minute + 1 if (y == after.year and m == after.month and d == after.day and h == after.hour) else 0
                    for mn in range(start_min, 60):
                        if mn in min_set:
                            return datetime.datetime(y, m, d, h, mn)

    return None
